// Meta A on the host (H3a): every sector of the images generated by
// tools/make_atr.py is read through StdioImageRepository -> DiskImage and its
// CRC32 is compared with the manifest computed independently (Python zlib).
// The geometry and D-8 results of AtrLayout are checked against images.csv.
// The same procedure runs on the ESP32 with the microSD in H3c.

#include <array>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <optional>

#include "rb/app/image_location.hpp"
#include "rb/domain/disk_image.hpp"
#include "rb/storage/stdio_image_repository.hpp"
#include "support/crc32.hpp"
#include "unity.h"

#ifndef RB_TEST_IMAGES_DIR
#error "RB_TEST_IMAGES_DIR must point to the output of tools/make_atr.py"
#endif

using rb::app::ImageLocation;
using rb::core::Result;
using rb::core::Span;
using rb::domain::DiskImage;
using rb::domain::ImageByteSource;
using rb::domain::SectorNumber;
using rb::storage::StdioImageRepository;

namespace {

struct ImageInfo {
    char name[32];
    unsigned sectors;
    unsigned sector_size;
    unsigned file_size;
    unsigned header_mismatch;
    unsigned trailing_bytes;
};

std::FILE* open_csv(const char* name)
{
    std::array<char, 300> path{};
    std::snprintf(path.data(), path.size(), "%s/%s", RB_TEST_IMAGES_DIR, name);
    std::FILE* file = std::fopen(path.data(), "r");
    TEST_ASSERT_NOT_NULL_MESSAGE(file, path.data());
    std::array<char, 256> header{};
    TEST_ASSERT_NOT_NULL(std::fgets(header.data(), static_cast<int>(header.size()), file));  // skip column names
    return file;
}

std::size_t load_images(std::array<ImageInfo, 8>& images)
{
    std::FILE* file = open_csv("images.csv");
    std::size_t count = 0;
    std::array<char, 256> line{};
    while (std::fgets(line.data(), static_cast<int>(line.size()), file) != nullptr) {
        TEST_ASSERT_TRUE(count < images.size());
        ImageInfo& info = images[count];
        const int fields = std::sscanf(line.data(), "%31[^,],%u,%u,%u,%u,%u", info.name, &info.sectors,
                                       &info.sector_size, &info.file_size, &info.header_mismatch,
                                       &info.trailing_bytes);
        TEST_ASSERT_EQUAL_INT(6, fields);
        ++count;
    }
    std::fclose(file);
    return count;
}

ImageLocation atr_location(const char* name)
{
    std::array<char, 48> text{};
    std::snprintf(text.data(), text.size(), "%s.atr", name);
    return ImageLocation::from(text.data()).value();
}

}  // namespace

void setUp(void) {}
void tearDown(void) {}

static void test_geometry_matches_the_generator(void)
{
    std::array<ImageInfo, 8> images{};
    const std::size_t count = load_images(images);
    TEST_ASSERT_EQUAL_size_t(5, count);

    StdioImageRepository<1> repository{RB_TEST_IMAGES_DIR};
    for (std::size_t i = 0; i < count; ++i) {
        const ImageInfo& info = images[i];
        ImageByteSource* source = repository.open(atr_location(info.name)).value();
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(info.file_size, source->size(), info.name);
        {
            Result<DiskImage> image = DiskImage::open(*source);
            TEST_ASSERT_TRUE_MESSAGE(image.ok(), info.name);
            const auto& layout = image.value().layout();
            TEST_ASSERT_EQUAL_UINT32_MESSAGE(info.sectors, layout.geometry().sectorCount(), info.name);
            TEST_ASSERT_EQUAL_UINT32_MESSAGE(info.sector_size, static_cast<unsigned>(layout.geometry().sectorSize()),
                                             info.name);
            TEST_ASSERT_EQUAL_MESSAGE(info.header_mismatch != 0, layout.headerSizeMismatch(), info.name);
            TEST_ASSERT_EQUAL_UINT32_MESSAGE(info.trailing_bytes, layout.ignoredTrailingBytes(), info.name);
        }
        repository.close(source);
    }
}

static void test_every_sector_crc_matches_the_manifest(void)
{
    StdioImageRepository<1> repository{RB_TEST_IMAGES_DIR};
    std::FILE* manifest = open_csv("manifest.csv");

    std::array<char, 32> current{};
    ImageByteSource* source = nullptr;
    std::optional<DiskImage> image;
    std::array<uint8_t, 256> buffer{};
    unsigned verified = 0;

    std::array<char, 256> line{};
    while (std::fgets(line.data(), static_cast<int>(line.size()), manifest) != nullptr) {
        char name[32] = {};
        unsigned sector = 0;
        unsigned offset = 0;
        unsigned length = 0;
        unsigned crc = 0;
        TEST_ASSERT_EQUAL_INT(5, std::sscanf(line.data(), "%31[^,],%u,%u,%u,%x", name, &sector, &offset, &length, &crc));

        if (std::strcmp(name, current.data()) != 0) {  // next image
            image.reset();
            repository.close(source);
            std::snprintf(current.data(), current.size(), "%s", name);
            source = repository.open(atr_location(name)).value();
            image.emplace(DiskImage::open(*source).value());
        }

        const Result<uint16_t> read = image->readSector(SectorNumber::from(static_cast<uint16_t>(sector)).value(),
                                                        Span<uint8_t>{buffer});
        TEST_ASSERT_TRUE_MESSAGE(read.ok(), line.data());
        TEST_ASSERT_EQUAL_UINT32_MESSAGE(length, read.value(), line.data());
        TEST_ASSERT_EQUAL_HEX32_MESSAGE(crc, rb::test::crc32(buffer.data(), length), line.data());
        ++verified;
    }
    image.reset();
    repository.close(source);
    std::fclose(manifest);

    TEST_ASSERT_EQUAL_UINT(720 + 1040 + 720 + 1440 + 720, verified);
    TEST_ASSERT_EQUAL_size_t(0, repository.open_count());
}

static void test_crc32_reference_vector(void)
{
    const char* check = "123456789";
    TEST_ASSERT_EQUAL_HEX32(0xCBF43926u, rb::test::crc32(reinterpret_cast<const uint8_t*>(check), 9));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_crc32_reference_vector);
    RUN_TEST(test_geometry_matches_the_generator);
    RUN_TEST(test_every_sector_crc_matches_the_manifest);
    return UNITY_END();
}
